import {ActionList, Button, Details, useDetails} from '@primer/react'
import {clsx} from 'clsx'
import {number as formatNumber} from '@github-ui/formatters'
import type {AffectedBranch} from '../types/affected-branch'
import type {Repository} from '../types/repository'
import {AffectedBranchItem} from './AffectedBranchItem'

export type AffectedBranchesProps = {
  affectedBranches: AffectedBranch[]
  repository: Repository

  /**
   * additionalHiddenBranchesCount is used to indicate the number of hidden branches that are not included in the
   * affectedBranches array. This is distinct from hasAdditionalHiddenBranches, which indicates that there are more
   * hidden branches but does not specify how many. Both can be set at the same time, additionalHiddenBranchesCount
   * is usually used when we know the exact number of hidden branches but have run into a limit on how many we want to
   * show, while hasAdditionalHiddenBranches is used when we know there are more hidden branches but don't know the
   * exact count or don't want to show it to the user.
   */
  additionalHiddenBranchesCount: number
  /**
   * hasAdditionalHiddenBranches is used to indicate that there are more hidden branches that are not included in the
   * affectedBranches array or in the additionalHiddenBranchesCount. This is needed because there are cases where we
   * know there are more hidden branches, but we don't know the exact count or don't want to show it to the user.
   */
  hasAdditionalHiddenBranches: boolean

  canWriteAlert: boolean
  staleAlertsDocsUrl: string
}

export function AffectedBranches({
  affectedBranches,
  repository,
  additionalHiddenBranchesCount,
  hasAdditionalHiddenBranches,
  canWriteAlert,
  staleAlertsDocsUrl,
}: AffectedBranchesProps) {
  const shownBranches = affectedBranches.slice(0, 5)
  const hiddenBranches = affectedBranches.slice(5)

  const emptyText =
    additionalHiddenBranchesCount > 0 || hasAdditionalHiddenBranches ? (
      <p className="color-fg-muted text-small">
        +{' '}
        {additionalHiddenBranchesCount > 0 ? (
          <>
            {hasAdditionalHiddenBranches && 'at least'} {formatNumber(additionalHiddenBranchesCount)}
          </>
        ) : (
          <>more</>
        )}
        {' branches (not shown)'}
      </p>
    ) : null

  const {getDetailsProps, open, setOpen} = useDetails({})

  return (
    <ActionList variant="full">
      {shownBranches.map(branch => (
        <AffectedBranchItem
          key={branch.name}
          affectedBranch={branch}
          repository={repository}
          canWriteAlert={canWriteAlert}
          staleAlertsDocsUrl={staleAlertsDocsUrl}
        />
      ))}
      <li>
        {hiddenBranches.length > 0 ? (
          <Details {...getDetailsProps()}>
            <Button
              as="summary"
              variant="link"
              className={clsx('f6', {
                'd-none': open,
              })}
            >
              View more
            </Button>
            {hiddenBranches.map(branch => (
              <AffectedBranchItem
                key={branch.name}
                affectedBranch={branch}
                repository={repository}
                canWriteAlert={canWriteAlert}
                staleAlertsDocsUrl={staleAlertsDocsUrl}
              />
            ))}
            {emptyText}
            <Button variant="link" className="f6" onClick={() => setOpen(false)}>
              View less
            </Button>
          </Details>
        ) : (
          emptyText
        )}
      </li>
    </ActionList>
  )
}
