import {useState, type RefObject} from 'react'
import {clsx} from 'clsx'
import {Dialog, Link, Heading} from '@primer/react'
import {codeScanningDeleteConfigurationsPath} from '@github-ui/paths'
import {verifiedFetch} from '@github-ui/verified-fetch'
import type {AffectedBranch} from '../types/affected-branch'
import type {Repository} from '../types/repository'
import {DeleteConfigurationItem} from './DeleteConfigurationItem'
import {DeleteConfigurationDialogFooter} from './DeleteConfigurationDialogFooter'

import styles from './DeleteConfigurationDialog.module.css'

export type DeleteConfigurationDialogProps = {
  affectedBranch: AffectedBranch
  repository: Repository

  canWriteAlert: boolean
  staleAlertsDocsUrl: string

  onClose: () => void
  onSuccess: () => void
  returnFocusRef: RefObject<HTMLElement | null>
}

type ConfigKey = {
  category: string
  toolName: string
}

// This is re-implemenation of app/assets/modules/react-shared/CodeScanning/DeleteConfigurationDialog.tsx for now
export function DeleteConfigurationDialog({
  affectedBranch,
  repository,
  canWriteAlert,
  staleAlertsDocsUrl,
  onClose,
  onSuccess,
  returnFocusRef,
}: DeleteConfigurationDialogProps) {
  const [outdatedConfigs, setOutdatedConfigs] = useState<ConfigKey[]>([])
  const onSubmit = async () => {
    const toBeMarkedOutdated = outdatedConfigs.map(config => {
      return {
        branch_name: affectedBranch.name,
        category: config.category,
        tool_name: config.toolName,
      }
    })

    await verifiedFetch(codeScanningDeleteConfigurationsPath({owner: repository.ownerLogin, repo: repository.name}), {
      method: 'POST',
      headers: {
        Accept: 'application/json',
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        mark_as_outdated: toBeMarkedOutdated,
      }),
    })
    onSuccess()
  }

  const deletableConfigs = affectedBranch.configs.filter(
    config =>
      !outdatedConfigs.some(
        outdatedConfig => outdatedConfig.category === config.category && outdatedConfig.toolName === config.toolName,
      ),
  )

  const showTool = new Set(affectedBranch.configs.map(config => config.toolName)).size > 1

  return (
    <Dialog
      onClose={onClose}
      returnFocusRef={returnFocusRef}
      title={
        <>
          Configurations analyzing <strong className="branch-name">{affectedBranch.name}</strong>
        </>
      }
      subtitle="The following configurations have reported this alert."
      width="xlarge"
      footerButtons={[
        {
          buttonType: 'default',
          content: 'Cancel',
          onClick: onClose,
        },
        {
          buttonType: 'primary',
          content: 'Save changes',
          onClick: onSubmit,
        },
      ]}
      renderFooter={({footerButtons}) => (
        <DeleteConfigurationDialogFooter
          footerText={
            outdatedConfigs.length > 0 && (
              <p className="fgColor-muted f6">
                <Link href={staleAlertsDocsUrl} inline>
                  Deleting a configuration
                </Link>{' '}
                may have an impact on the status of other alerts on the same branch.
              </p>
            )
          }
          footerButtons={footerButtons ?? []}
        />
      )}
    >
      {deletableConfigs.length > 0 ? (
        <ul className={clsx('pr-pt-3', styles.deletableConfigsContainer, styles.deletableConfigsListContainer)}>
          {deletableConfigs.map(config => (
            <DeleteConfigurationItem
              key={`${config.category}/${config.toolName}`}
              config={config}
              canWriteAlert={canWriteAlert}
              showTool={showTool}
              onDelete={() => {
                setOutdatedConfigs(oldConfigs => {
                  if (oldConfigs.some(c => c.category === config.category && c.toolName === config.toolName)) {
                    return oldConfigs
                  }
                  return [...oldConfigs, {category: config.category, toolName: config.toolName}]
                })
              }}
            />
          ))}
        </ul>
      ) : (
        <div className={clsx('pr-pt-3', styles.deletableConfigsContainer)}>
          <div className="d-flex flex-column flex-justify-center flex-items-center">
            <Heading as="h4" className="f4 text-bold">
              All configurations deleted
            </Heading>
            <p className="fgColor-muted">Deleting all configurations will close this alert as fixed.</p>
          </div>
        </div>
      )}
    </Dialog>
  )
}
