import {AnchoredOverlay, Label, IconButton, Link} from '@primer/react'
import {InfoIcon} from '@primer/octicons-react'

import type {RuntimeRisk} from '../types/runtime-risk'
import {useState} from 'react'
import styles from './RuntimeRisks.module.css'

interface RuntimeRisksProps {
  risks?: RuntimeRisk[]
}

export function RuntimeRisks({risks}: RuntimeRisksProps) {
  const [open, setOpen] = useState(false)

  if (!risks || risks.length === 0) return null

  return (
    <>
      <div className="d-flex flex-items-center">
        <h3 className="h6 color-fg-muted mb-2">Runtime risks</h3>
        <AnchoredOverlay
          open={open}
          onOpen={() => setOpen(true)}
          onClose={() => setOpen(false)}
          width="small"
          height="auto"
          side="outside-top"
          renderAnchor={anchorProps => (
            <IconButton
              {...anchorProps}
              aria-label="About runtime risks"
              icon={InfoIcon}
              size="small"
              variant="invisible"
              className="mb-2 ml-1"
            />
          )}
        >
          <div className={styles.OverlayContent}>
            <h5 className="mb-2">Runtime Risks</h5>
            <p>
              Active deployment records impacted by this vulnerability have been detected and tagged with runtime risks.
            </p>
            <Link href="https://docs.github.com/en/code-security/how-tos/manage-security-alerts/remediate-alerts-at-scale/filtering-alerts-in-security-overview#production-context-filters">
              Learn more
            </Link>
          </div>
        </AnchoredOverlay>
      </div>
      <div className="d-flex flex-wrap">
        {risks.map(risk => (
          <Label key={risk} variant="secondary" className="mb-1 mr-1">
            {risk}
          </Label>
        ))}
      </div>
    </>
  )
}
