import {clsx} from 'clsx'
import {ShieldCheckIcon, ShieldIcon, TrashIcon} from '@primer/octicons-react'
import {Heading, IconButton, RelativeTime, Tooltip} from '@primer/react'
import type {AffectedBranchConfig} from '../types/affected-branch-config'
import styles from './DeleteConfigurationItem.module.css'

export type DeleteConfigurationItemProps = {
  config: AffectedBranchConfig

  canWriteAlert: boolean
  showTool: boolean

  onDelete: () => void
}

export function DeleteConfigurationItem({config, canWriteAlert, showTool, onDelete}: DeleteConfigurationItemProps) {
  const isFixed = !!config.fixedAt

  return (
    <li className="d-flex flex-grow-0 flex-row">
      <div className={isFixed ? 'fgColor-done' : 'fgColor-success'}>
        {isFixed ? <ShieldCheckIcon /> : <ShieldIcon />}
      </div>
      <div className={clsx('d-flex flex-column ml-1 mb-1 mr-1 mt-0', styles.mainContent)}>
        <Heading as="h5" className="f5">
          {config.category || <>API Upload</>} {showTool && <> ({config.toolName})</>}
        </Heading>
        <p className="fgColor-muted">
          Last updated <RelativeTime datetime={config.createdAt} tense="past" />
        </p>
      </div>
      <div>
        {canWriteAlert ? (
          <Tooltip text="Delete configuration" direction="sw">
            <IconButton icon={TrashIcon} variant="invisible" aria-label="Delete configuration" onClick={onDelete} />
          </Tooltip>
        ) : (
          <IconButton icon={TrashIcon} variant="invisible" aria-label="Delete configuration" disabled />
        )}
      </div>
    </li>
  )
}
