import {testIdProps} from '@github-ui/test-id-props'
import {Text} from '@primer/react'
import {clsx} from 'clsx'

import styles from './AlertMetadata.module.css'
import {AlertMetadataContent} from './AlertMetadataContent'
import {AlertMetadataHeader} from './AlertMetadataHeader'
import type {AlertMetadataProps} from './types'

export const AlertMetadata = ({testId, children, title, ...headerProps}: AlertMetadataProps) => (
  <Text
    as="div"
    size="small"
    className={clsx(styles.AlertMetadata, 'color-fg-muted')}
    {...(testId ? testIdProps(testId) : {})}
  >
    {title && <AlertMetadataHeader title={title} {...headerProps} />}
    <AlertMetadataContent>{children}</AlertMetadataContent>
  </Text>
)
