import {useMemo} from 'react'
import {AlertIcon, CircleSlashIcon, NoteIcon} from '@primer/octicons-react'
import {Label, Tooltip} from '@primer/react'
import {SecuritySeverity} from '@github-ui/code-scanning-shared/types/security-severity'
import {RuleSeverity} from '@github-ui/code-scanning-shared/types/rule-severity'
import {Section} from './Section'

export type SeveritySectionProps = {
  ruleSeverity: RuleSeverity
  securitySeverity: SecuritySeverity | null
  severityFilterUrl: string
}

export function SeveritySection({ruleSeverity, securitySeverity, severityFilterUrl}: SeveritySectionProps) {
  const severityLabel = useMemo(() => {
    switch (securitySeverity) {
      case SecuritySeverity.Low:
        return {
          variant: 'secondary' as const,
          label: 'Low',
        }
      case SecuritySeverity.Medium:
        return {
          variant: 'attention' as const,
          label: 'Medium',
        }
      case SecuritySeverity.High:
        return {
          variant: 'severe' as const,
          label: 'High',
        }
      case SecuritySeverity.Critical:
        return {
          variant: 'danger' as const,
          label: 'Critical',
        }
    }

    switch (ruleSeverity) {
      case RuleSeverity.Note:
        return {
          variant: 'secondary' as const,
          label: 'Note',
          icon: NoteIcon,
          iconColor: 'color-fg-default' as const,
        }
      case RuleSeverity.Warning:
        return {
          variant: 'secondary' as const,
          label: 'Warning',
          icon: AlertIcon,
          iconColor: 'color-fg-attention' as const,
        }
      case RuleSeverity.Error:
        return {
          variant: 'secondary' as const,
          label: 'Error',
          icon: CircleSlashIcon,
          iconColor: 'color-fg-danger' as const,
        }
    }

    return undefined
  }, [securitySeverity, ruleSeverity])

  if (!severityLabel) {
    return null
  }

  return (
    <Section title="Severity">
      <Tooltip text={`Filter alerts by '${severityLabel.label.toLowerCase()}' severity.`}>
        <Label
          as="a"
          href={severityFilterUrl}
          variant={severityLabel.variant}
          size="large"
          className="d-inline-flex flex-items-center"
        >
          {severityLabel.icon && (
            <span className={`pr-1 ${severityLabel.iconColor}`}>
              <severityLabel.icon />
            </span>
          )}
          <span>{severityLabel.label}</span>
        </Label>
      </Tooltip>
    </Section>
  )
}
