import {AlertMetadata} from '@github-ui/platform-patterns/AlertPageSidebar'
import {ErrorBoundary} from '@github-ui/react-core/error-boundary'
import type {ReactNode} from 'react'

export type SectionProps = {
  title: string
  children: ReactNode
  hideTitle?: boolean
}

export function Section({title, children, hideTitle = false}: SectionProps) {
  return (
    <AlertMetadata title={hideTitle ? undefined : title}>
      <ErrorBoundary fallback={<span>There was an error rendering this section.</span>}>{children}</ErrorBoundary>
    </AlertMetadata>
  )
}
